export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface Customer {
  yearsWithMHPCO: number;
}

export interface History {
  previousContracts: number;
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const LOYALTY_DISCOUNT_PERCENT = 20;
const LOYALTY_YEARS = 2;
const FOLLOW_UP_DISCOUNT_PERCENT = 15;
const CURSE_SURCHARGE_PERCENT = 50;
const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
const HIGH_ENCHANTMENT_LEVEL = 5;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

const COMPONENT_TYPES = new Set(['rune', 'moonstone']);
const COMPONENT_BASE_PREMIUM = 25;
const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_BASE_PREMIUM = 60;

function componentsBasePremium(count: number): number {
  return count === COMPONENT_BLOCK_SIZE ? COMPONENT_BLOCK_BASE_PREMIUM : count * COMPONENT_BASE_PREMIUM;
}

function policyBasePremium(items: Item[]): number {
  const mainItems = items.filter((item) => item.type in BASE_PREMIUMS);
  const componentCounts = new Map<string, number>();
  for (const item of items) {
    if (!(item.type in BASE_PREMIUMS)) {
      componentCounts.set(item.type, (componentCounts.get(item.type) ?? 0) + 1);
    }
  }
  const mainBase = mainItems.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
  const componentBase = [...componentCounts.values()].reduce(
    (sum, count) => sum + componentsBasePremium(count),
    0,
  );
  return mainBase + componentBase;
}

function percentOf(amount: number, percent: number): number {
  return (amount * percent) / 100;
}

function itemSurcharge(item: Item): number {
  let percent = 0;
  if (item.cursed) percent += CURSE_SURCHARGE_PERCENT;
  if ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL) percent += HIGH_ENCHANTMENT_SURCHARGE_PERCENT;
  return percentOf(BASE_PREMIUMS[item.type], percent);
}

function policyModifierPercent(customer: Customer, history: History): number {
  let percent = FIRST_INSURANCE_SURCHARGE_PERCENT;
  if (customer.yearsWithMHPCO >= LOYALTY_YEARS) percent -= LOYALTY_DISCOUNT_PERCENT;
  if (history.previousContracts > 0) percent -= FOLLOW_UP_DISCOUNT_PERCENT;
  return percent;
}

export function quote(items: Item[], customer: Customer, history: History): number {
  for (const item of items) {
    if (!(item.type in BASE_PREMIUMS) && !COMPONENT_TYPES.has(item.type)) {
      throw new Error(`Unknown item type: ${item.type}`);
    }
  }
  const base = policyBasePremium(items);
  const itemSurcharges = items
    .filter((item) => item.type in BASE_PREMIUMS)
    .reduce((sum, item) => sum + itemSurcharge(item), 0);
  return Math.ceil(base + itemSurcharges + percentOf(base, policyModifierPercent(customer, history)) + PROCESSING_FEE);
}

