    sum([...countByType(components).values()].map(componentsBasePremium));
  const itemPremiums = sum(mainItems.map(mainItemPremium)) + sum([...countByType(components).values()].map(componentsBasePremium));

  return Math.ceil(itemPremiums + percentOf(policyBase, policyModifierPercent(customer, history)) + PROCESSING_FEE);
